struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* build(const vector<string>& t) {
    if (t.empty() || t[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(t[0]));
    vector<TreeNode*> q{root};
    size_t head = 0;
    int i = 1, n = t.size();
    while (head < q.size() && i < n) {
        TreeNode* node = q[head++];
        if (i < n) {
            if (t[i] != "null") {
                node->left = new TreeNode(stoi(t[i]));
                q.push_back(node->left);
            }
            i++;
        }
        if (i < n) {
            if (t[i] != "null") {
                node->right = new TreeNode(stoi(t[i]));
                q.push_back(node->right);
            }
            i++;
        }
    }
    return root;
}

int best = INT_MIN;

int gain(TreeNode* node) {
    if (!node) return 0;
    int left = max(gain(node->left), 0);
    int right = max(gain(node->right), 0);
    best = max(best, node->val + left + right);
    return node->val + max(left, right);
}

int main() {
    vector<string> tok;
    string s;
    while (cin >> s) tok.push_back(s);
    TreeNode* root = build(tok);
    gain(root);
    cout << best << '\n';
    return 0;
}

