class Trie {
    struct Node {
        Node* child[26];
        bool end;
        Node() : end(false) { memset(child, 0, sizeof(child)); }
    };

public:
    Trie() { root = new Node(); }

    void insert(string word) {
        Node* cur = root;
        for (char ch : word) {
            int c = ch - 'a';
            if (!cur->child[c]) cur->child[c] = new Node();
            cur = cur->child[c];
        }
        cur->end = true;
    }

    bool search(string word) {
        Node* cur = walk(word);
        return cur && cur->end;
    }

    bool startsWith(string prefix) { return walk(prefix) != nullptr; }

private:
    Node* root;

    Node* walk(const string& s) {
        Node* cur = root;
        for (char ch : s) {
            cur = cur->child[ch - 'a'];
            if (!cur) return nullptr;
        }
        return cur;
    }
};

