             string& path, vector<string>& res) {
        if (i == (int)digits.size()) {
            res.push_back(path);
            return;
        }
        for (char ch : table[digits[i] - '0']) {
            path.push_back(ch);
            dfs(digits, i + 1, table, path, res);
            path.pop_back();
        }
    }
};

