class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        rows = board.size();
        cols = board[0].size();
        this->word = word;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (dfs(board, r, c, 0)) return true;
        return false;
    }

private:
    int rows, cols;
    string word;

    bool dfs(vector<vector<char>>& board, int r, int c, int i) {
        if (i == (int)word.size()) return true;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        if (board[r][c] != word[i]) return false;
        char tmp = board[r][c];
        board[r][c] = '#';
        bool found = dfs(board, r + 1, c, i + 1) || dfs(board, r - 1, c, i + 1) ||
                     dfs(board, r, c + 1, i + 1) || dfs(board, r, c - 1, i + 1);
        board[r][c] = tmp;
        return found;
    }
};

